import { describe, expect, test } from "vitest";

describe("tenant provisioning v1 contract — Story 12.1 ATDD", () => {
  test.skip("[P0] 12.1-UNIT-001 strictly allow-lists v1 fields and rejects unsupported schema, SQL, secrets, raw rates, pending modules, and deferred fields", async () => {
    const { decodeProvisioningRequest } = await import("@/server/commands/provisioning/validation");
    expect(() => decodeProvisioningRequest({ schema_version: 2 })).toThrow(/UNSUPPORTED_SCHEMA_VERSION/);
    expect(() => decodeProvisioningRequest({ schema_version: 1, arbitrary_sql: "select 1" })).toThrow(/UNSUPPORTED_FIELD/);
  });

  test.skip("[P0] 12.1-UNIT-002 canonicalizes Swedish organization/VAT/email identities and rejects personnummer, non-SE, bad checksums, mismatches, and invalid email syntax", async () => {
    const { canonicalizeProvisioningRequest } = await import("@/server/commands/provisioning/validation");
    const canonical = canonicalizeProvisioningRequest({ schema_version: 1, request_id: crypto.randomUUID(), legal_name: "Elpro AB", country_code: "SE", organization_number: "556 123-4567", vat_registration_number: " se556123456701 ", first_admin_name: "Ada", first_admin_email: " Ada+ops@EXAMPLE.SE ", baseline_profile_id: "standard-se", baseline_profile_version: 1, subscription_plan_id: "pro", subscription_status: "active", included_user_count: 5, additional_user_price_ore: 12500, contract_start_date: "2026-10-01" });
    expect(canonical).toMatchObject({ normalizedOrganizationNumber: "5561234567", vatRegistrationNumber: "SE556123456701", firstAdminEmail: "ada+ops@example.se" });
    expect(() => canonicalizeProvisioningRequest({ ...canonical, organization_number: "850101-1234" } as never)).toThrow(/PERSONNUMMER|organization/i);
  });

  test.skip("[P0] 12.1-UNIT-003 permits only documented handoff states and ready's exact persisted predicate", async () => {
    const { canTransitionProvisioning, canMarkTenantProvisioningReady } = await import("@/server/commands/provisioning/validation");
    expect(canTransitionProvisioning("pending_first_admin_invite", "first_admin_invite_unknown")).toBe(true);
    expect(canTransitionProvisioning("first_admin_invite_requested", "ready")).toBe(false);
    expect(canMarkTenantProvisioningReady({ databaseCommitted: true, baselineRecorded: true, membershipActive: true, authUserId: crypto.randomUUID(), normalizedAuthEmail: "ada@example.se", normalizedInvitationEmail: "ada@example.se", unresolvedFailure: false })).toBe(true);
    expect(canMarkTenantProvisioningReady({ databaseCommitted: true, baselineRecorded: true, membershipActive: true, authUserId: null, normalizedAuthEmail: "ada@example.se", normalizedInvitationEmail: "ada@example.se", unresolvedFailure: false })).toBe(false);
  });
});

import { describe, expect, test } from "vitest";
import { isLocalStackReachable } from "../../support/test-env";
import { skipUnlessStack } from "../../support/stack-gate";

const strictRequest = () => ({ schema_version: 1, request_id: crypto.randomUUID(), legal_name: "Provisioned Elpro AB", country_code: "SE", organization_number: "5561234567", first_admin_name: "Ada Admin", first_admin_email: "ada.provision@example.se", baseline_profile_id: "standard-se", baseline_profile_version: 1, subscription_plan_id: "pro", subscription_status: "active", included_user_count: 5, additional_user_price_ore: 12500, contract_start_date: "2026-10-01" });

describe("provision_tenant command — Story 12.1 ATDD", () => {
  test.skip("[P0] 12.1-INT-003 atomically persists canonical identity/request, exact baseline, tenant, invited first Admin, pending state, and audit before Auth", async (ctx) => {
    if (skipUnlessStack(ctx, await isLocalStackReachable())) return;
    const { executeApprovedProvisioning } = await import("../../factories/platform-operators");
    const result = await executeApprovedProvisioning(strictRequest());
    expect(result).toMatchObject({ tenantId: expect.any(String), provisioningState: "pending_first_admin_invite", baseline: { id: "standard-se", version: 1, contentHash: expect.any(String) }, authCallObservedAfterCommit: true });
  });

  test.skip("[P0] 12.1-INT-004 injected failure at each transactional write point rolls back tenant, membership, idempotency, and audit", async () => {
    const { executeApprovedProvisioning } = await import("../../factories/platform-operators");
    for (const failAt of ["tenant", "baseline", "membership", "idempotency", "audit"] as const) await expect(executeApprovedProvisioning(strictRequest(), { failAt })).rejects.toMatchObject({ rolledBack: true });
  });

  test.skip("[P0] 12.1-INT-005 dry run is complete and zero-write; execution requires original request, request ID, hash, approval, and an unchanged immutable baseline", async () => {
    const { previewProvisioningForTest, executeApprovedProvisioning } = await import("../../factories/platform-operators");
    const input = strictRequest(); const preview = await previewProvisioningForTest(input);
    expect(preview).toMatchObject({ schema_version: 1, request_id: input.request_id, normalized_identity: expect.any(Object), baseline: expect.objectContaining({ id: expect.any(String), version: expect.any(Number), content_hash: expect.any(String) }), proposed_values: expect.any(Object), first_admin: expect.any(Object), audit_events: expect.any(Array), preview_hash: expect.any(String), writes: 0 });
    await expect(executeApprovedProvisioning(input, { previewHash: "changed" })).rejects.toMatchObject({ code: "PREVIEW_STALE" });
  });

  test.skip("[P0] 12.1-INT-006 same UUID/hash reconciles without provider work; conflicts and all-status same-identity replays cannot mutate or duplicate", async () => {
    const { executeApprovedProvisioning } = await import("../../factories/platform-operators"); const input = strictRequest(); const first = await executeApprovedProvisioning(input);
    expect(await executeApprovedProvisioning(input)).toMatchObject({ tenantId: first.tenantId, providerCallCount: 0 });
    await expect(executeApprovedProvisioning({ ...input, legal_name: "Changed AB" })).rejects.toMatchObject({ code: "IDEMPOTENCY_CONFLICT" });
    await expect(executeApprovedProvisioning({ ...input, request_id: crypto.randomUUID() })).rejects.toMatchObject({ code: "ALREADY_PROVISIONED" });
  });

  test.skip("[P0] 12.1-INT-007 concurrent equal canonical identities produce one tenant and one effective invite intent", async () => {
    const { executeApprovedProvisioning } = await import("../../factories/platform-operators"); const input = strictRequest(); const [a, b] = await Promise.allSettled([executeApprovedProvisioning(input), executeApprovedProvisioning({ ...input, request_id: crypto.randomUUID() })]);
    expect([a, b].filter((result) => result.status === "fulfilled")).toHaveLength(1);
  });

  test.skip("[P0] 12.1-INT-008 explicit retry records requested/failed truthfully, makes one provider call, preserves one invitation through attempt three, and limits attempt four", async () => {
    const { retryFirstAdminInviteForTest } = await import("../../factories/platform-operators");
    const result = await retryFirstAdminInviteForTest({ providerOutcome: "accepted" });
    expect(result).toMatchObject({ provisioningState: "first_admin_invite_requested", providerCallCount: 1, attemptNumber: 1 });
    await expect(retryFirstAdminInviteForTest({ attemptNumber: 4 })).rejects.toMatchObject({ code: "INVITE_ATTEMPT_LIMIT" });
  });

  test.skip("[P0] 12.1-INT-009 timeout/lost response stays unknown, reconciliation reuses bound token, and raw-token canary is absent from RPC/audit/log/browser output", async () => {
    const { retryFirstAdminInviteForTest } = await import("../../factories/platform-operators"); const rawTokenCanary = "raw-token-canary-" + crypto.randomUUID();
    const result = await retryFirstAdminInviteForTest({ providerOutcome: "timeout", rawTokenCanary });
    expect(result).toMatchObject({ provisioningState: "first_admin_invite_unknown", providerCallCount: 1, tokenReused: true });
    expect(JSON.stringify(result)).not.toContain(rawTokenCanary);
    await expect(retryFirstAdminInviteForTest({ attemptNumber: 4, freshPreviewAndApproval: true })).resolves.toMatchObject({ tokenRotated: true });
  });

  test.skip("[P0] 12.1-INT-012 writes correlated nonsecret audit transitions and leaves preview without any audit row", async () => {
    const { inspectProvisioningAuditForTest } = await import("../../factories/platform-operators");
    expect(await inspectProvisioningAuditForTest()).toMatchObject({ approverFromAuthUid: true, requestId: expect.any(String), previewHash: expect.any(String), baselineContentHash: expect.any(String), sanitizedOutcome: expect.any(String), containsRawInvitationToken: false, previewAuditRows: 0 });
  });
});

import { describe, expect, test } from "vitest";
import { isLocalStackReachable } from "../../support/test-env";
import { skipUnlessStack } from "../../support/stack-gate";

describe("platform operator authority — Story 12.1 ATDD", () => {
  test.skip("[P0] 12.1-INT-001 operator self-read succeeds while tenant roles, orphan, and anonymous identities cannot enumerate platform_operators", async (ctx) => {
    if (skipUnlessStack(ctx, await isLocalStackReachable())) return;
    const { createPlatformOperatorFixture, cleanupPlatformOperatorFixture, makePlatformOperatorClient } = await import("../../factories/platform-operators"); const fixture = await createPlatformOperatorFixture();
    try { expect((await makePlatformOperatorClient(fixture.operator).from("platform_operators").select("user_id")).error).toBeNull(); for (const subject of [fixture.tenantAdmin, fixture.orphan, fixture.anonymous]) expect((await makePlatformOperatorClient(subject).from("platform_operators").select("user_id")).data).toEqual([]); } finally { await cleanupPlatformOperatorFixture(fixture); }
  });

  test.skip("[P0] 12.1-INT-010 tenant roles, orphan, anonymous, absent/forged claims, and direct callers receive generic pre-validation denial with zero effects", async () => {
    const { attemptProvisioningAsEveryUnauthorizedIdentity } = await import("../../factories/platform-operators");
    for (const result of await attemptProvisioningAsEveryUnauthorizedIdentity()) { expect(result).toMatchObject({ code: "42501", generic: true, effects: 0, tenantData: null }); }
  });

  test.skip("[P0] 12.1-INT-011 a provisioning command cannot read or mutate foreign tenant state or leak its existence", async () => {
    const { assertProvisioningTenantIsolation } = await import("../../factories/platform-operators");
    expect(await assertProvisioningTenantIsolation()).toEqual({ foreignDigestUnchanged: true, foreignExistenceLeaked: false });
  });
});

import { describe, expect, test } from "vitest";
import { isLocalStackReachable } from "../../support/test-env";
import { skipUnlessStack } from "../../support/stack-gate";

describe("tenant provisioning migration reset — Story 12.1 ATDD", () => {
  test.skip("[P0] 12.1-INT-013 clean reset contains exact platform objects, baseline catalogue, all-status uniqueness, provisioning/attempt facts, grants, indexes, and manifest inventories", async (ctx) => {
    if (skipUnlessStack(ctx, await isLocalStackReachable())) return;
    const { adminQuery } = await import("../../factories/admin-sql");
    const objects = await adminQuery<{ exists: boolean }>("select to_regclass('public.platform_operators') is not null as exists");
    expect(objects[0]?.exists).toBe(true);
    const indexes = await adminQuery<{ indexdef: string }>("select indexdef from pg_indexes where schemaname='public' and tablename='tenants'");
    expect(indexes.map((row) => row.indexdef).join(" ")).toMatch(/normalized_organization_number/i);
  });
});

